// Generic Jotform submission formatter — flattens every answer field into
// Slack mrkdwn, skipping empty values and Jotform's nested name objects when
// they're blank. Truncates long answers, strips control chars, JSON-escapes
// for safe embedding inside the Slack node's blocksUi textarea.
//
// Inputs are whatever the Jotform webhook delivers; no field names are
// hardcoded — the formatter walks the entire payload.

const payload = $json.body ?? $json;
const data = Array.isArray(payload) ? payload[0] : payload;

const MAX_ANSWER_CHARS = 1500;

function normalizeNewlines(s) {
  return s.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

function stripBadControlChars(s) {
  return s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
}

function safeAnswer(val) {
  if (val === null || val === undefined) return '';

  // Jotform name-field object
  if (typeof val === 'object' && !Array.isArray(val)) {
    const hasFirstLast = ('first' in val) || ('last' in val);
    if (hasFirstLast) {
      const first = String(val.first ?? '').trim();
      const last = String(val.last ?? '').trim();
      return `${first} ${last}`.trim();
    }
  }

  let s;
  if (typeof val === 'string') s = val;
  else if (typeof val === 'number' || typeof val === 'boolean' || typeof val === 'bigint') s = String(val);
  else {
    try { s = JSON.stringify(val, null, 2); }
    catch { s = String(val); }
  }

  s = stripBadControlChars(normalizeNewlines(s)).trim();

  if (s.length > MAX_ANSWER_CHARS) {
    s = s.slice(0, MAX_ANSWER_CHARS - 20) + '\n…(truncated)';
  }

  return s;
}

function jsonEscapeForInlineString(s) {
  return s
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\n/g, '\\n');
}

const lines = [];
for (const [key, val] of Object.entries(data)) {
  const answer = safeAnswer(val);
  if (!answer) continue;

  const safeKey = stripBadControlChars(normalizeNewlines(String(key))).trim();
  if (!safeKey) continue;

  lines.push(`*${safeKey}:*\n${answer}`);
}

const mrkdwn = lines.join('\n\n');
const formId = $node['Jotform Trigger'].parameter?.form ?? '';

$json.slackFieldsMrkdwn = mrkdwn;
$json.slackFieldsMrkdwnEscaped = jsonEscapeForInlineString(mrkdwn);
$json.formUrl = data.formUrl ?? `https://www.jotform.com/form/${formId}`;
$json.submissionUrl = data.submissionUrl ?? `https://www.jotform.com/inbox/${formId}/`;

return $json;

